from pathlib import Path
import re, json, hashlib

ROOT=Path('.')

def read(path): return (ROOT/path).read_text()
def write(path,text): (ROOT/path).write_text(text)
def rep(path,old,new,count=1):
    text=read(path)
    if old not in text: raise SystemExit(f'MISSING REPLACEMENT in {path}: {old[:120]!r}')
    text=text.replace(old,new,count)
    write(path,text)
def rex(path,pattern,repl,count=1,flags=re.S):
    text=read(path)
    new,n=re.subn(pattern,repl,text,count=count,flags=flags)
    if n!=count: raise SystemExit(f'REGEX REPLACEMENT count {n} != {count} in {path}: {pattern[:120]}')
    write(path,new)
def insert_before(path,marker,block):
    text=read(path)
    if marker not in text: raise SystemExit(f'MISSING MARKER in {path}: {marker[:120]!r}')
    write(path,text.replace(marker,block+marker,1))

