verify=f'''import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';import crypto from 'node:crypto';\nconst files=['workbook.js','hash.js','workflow-schema.js','test-runtime.js','workflow-engine.js','prompt-engine.js','response-ingestion.js'];const ctx={{console,TextEncoder,TextDecoder,crypto:crypto.webcrypto,structuredClone,Event:class Event{{constructor(type){{this.type=type}}}},dispatchEvent:()=>{{}}}};ctx.globalThis=ctx;vm.createContext(ctx);for(const f of files)vm.runInContext(fs.readFileSync(f,'utf8'),ctx,{{filename:f}});\nconst core=ctx.closedLoopCore,schema=ctx.closedLoopWorkflowSchema,engine=ctx.closedLoopWorkflowEngine,prompts=ctx.closedLoopPromptEngine,ingestion=ctx.closedLoopResponseIngestion,runtime=ctx.closedLoopTestRuntime;\nassert.equal(core.PROJECT_SCHEMA,'closed-loop-project/3');assert.equal(schema.RESPONSE_SCHEMA,'closed-loop-stage-response/3');assert.equal(core.STAGE_COUNT,30);assert.equal(core.WORKFLOW_ID,'mobile-closed-loop/30');assert.equal(core.STAGES[15].title,'CORRECT THE ROOT CAUSE');assert.deepEqual([...schema.TEST_IR.executableKinds],['NONE','TEST_IR']);for(const op of ['PARSE_XML','SELECT_XML'])assert(schema.TEST_IR.operations.includes(op));assert(!schema.TEST_IR.operations.includes('ASSERT_NE'));assert.equal(schema.RECORD_SCHEMAS.tests.fieldDefinitions.EXECUTABLE_SPEC_VERSION.producer,'APPLICATION');\nconst p=core.createBlankState('JOB-CONFORMANCE');p.job.EXACT_USER_OBJECTIVE_VERBATIM='Build the requested thing exactly.';p.job.EXPLICIT_USER_REQUIREMENTS='Must retain every project requirement once supplied.';p.job.SUPPLIED_MATERIALS_INVENTORY='intent.txt';engine.ensureShape(p);engine.recordHumanInputVersion(p,['EXACT_USER_OBJECTIVE_VERBATIM','EXPLICIT_USER_REQUIREMENTS','SUPPLIED_MATERIALS_INVENTORY']);engine.recalculate(p);const intake=engine.stageOneAccounting(p);assert(intake.total>=3);const s1=prompts.buildPromptRecord(1,p);assert(s1.prompt.includes('APPLICATION-OWNED INTAKE COVERAGE MANIFEST'));assert(!/For PATENT \/ REGULATED FILING/i.test(s1.prompt));assert(s1.prompt.includes('EXECUTION COMMAND — DO THE CURRENT STAGE WORK NOW'));\n// Simulate complete accepted Stage 1 semantic capture directly as application fixture evidence.\np.projectData.intakeClassifications=intake.manifest.map((u,i)=>({{id:`INTAKE-CLASS-${{i}}`,stage:1,active:true,scope:u.scope,fields:{{CLASSIFICATION_ID:`INTAKE-CLASS-${{i}}`,INPUT_UNIT_ID:u.id,DISPOSITION:'INCORPORATED_IN_JOB_DEFINITION',REASON:'captured',STATUS:'CLASSIFIED'}},CLASSIFICATION_ID:`INTAKE-CLASS-${{i}}`,INPUT_UNIT_ID:u.id,DISPOSITION:'INCORPORATED_IN_JOB_DEFINITION',REASON:'captured',STATUS:'CLASSIFIED'}}));const source=intake.manifest.find(x=>x.SOURCE_LOCATION==='job.EXPLICIT_USER_REQUIREMENTS')||intake.manifest[0];p.projectData.humanStatements=[{{id:'HUMAN-STATEMENT-1',stage:1,active:true,scope:source.scope,fields:{{STATEMENT_ID:'HUMAN-STATEMENT-1',INPUT_UNIT_ID:source.id,EXACT_STATEMENT:'Must retain every project requirement once supplied.',STATEMENT_CLASS:'REQUIREMENT',NORMATIVE_FORCE:'MUST',NOTES:'',STATUS:'ACTIVE'}},STATEMENT_ID:'HUMAN-STATEMENT-1',INPUT_UNIT_ID:source.id,EXACT_STATEMENT:'Must retain every project requirement once supplied.',STATEMENT_CLASS:'REQUIREMENT',NORMATIVE_FORCE:'MUST',NOTES:'',STATUS:'ACTIVE'}}];p.stages[1].agentData={{EXACT_DELIVERABLE_REQUESTED:'Requested deliverable',ASSUMPTIONS:'NONE',UNKNOWN_INFORMATION:'NONE',INPUT_SET_CONTENTS:'Captured'}};p.stages[1].acceptedData=p.stages[1].agentData;p.projectData.acceptedChanges.push({{changeId:'CHANGE-1',stage:1,status:'COMMITTED',responseType:'DATA_PROPOSAL'}});p.stages[1].acceptedDataChangeIds=['CHANGE-1'];p.projectData.stageConfirmations.push({{confirmationId:'CONF-1',stage:1,confirmed:true,acceptedChangeId:'CHANGE-1',inputVersion:p.job.CURRENT_INPUT_VERSION}});engine.recalculate(p);engine.buildObligationManifest(p);const obligations=engine.stageFourAccounting(p).manifest;assert(obligations.some(x=>String(x.OBLIGATION_TEXT).includes('retain every project requirement')));const s4=prompts.buildPromptRecord(4,p);assert(s4.prompt.includes('APPLICATION-OWNED STAGE 04 OBLIGATION INPUT MANIFEST'));assert(!/attach or resend the original intent file/i.test(s4.prompt.split('EXECUTION / ARTIFACT HANDOFF')[0])||s4.prompt.includes('Do not ask the human to attach, resend'));assert(!s4.prompt.includes('FILES YOU MUST RECEIVE\n- ORIGINAL'));\nconst style=fs.readFileSync('index.html','utf8').match(/<style>([\\s\\S]*?)<\\/style>/)[1];assert.equal(crypto.createHash('sha256').update(style).digest('hex'),'{visual_sha}','Visual CSS changed from the user-established baseline');assert(/\\.expandable-prompt\\{{max-height:280px\\}}/.test(style));\nconst action=engine.operationalNextAction(p,4);assert.equal(typeof action,'object');for(const k of ['actionType','heading','explanation','primaryButton','secondaryAction','filesToSend','filesToWithhold','expectedReturnFiles','blockingReason','canonicalStateChanged','newPromptRequired'])assert(Object.hasOwn(action,k));\nconst spec={{version:'closed-loop-test-spec/1',steps:[{{op:'LOAD_ARTIFACT',binding:'PRODUCT'}},{{op:'READ_BYTES'}},{{op:'DECODE_UTF8',encoding:'utf-8'}},{{op:'PARSE_JSON'}},{{op:'SELECT_JSON_PATH',path:'$.items'}},{{op:'COUNT'}},{{op:'ASSERT_EQ',value:10}}]}};assert(runtime.validateSpec(spec).valid);assert(!runtime.validateSpec({{version:'closed-loop-test-spec/1',steps:[{{op:'ASSERT_EQ',value:1,code:'evil()'}}]}}).valid);\nconsole.log('verify-controlling-spec: PASS');\n'''
write('verify-controlling-spec.mjs',verify)

# Update pages workflow script order and add controlling verifier. Preserve one Pages workflow.
pages=read('.github/workflows/pages.yml')
pages=pages.replace("const expected=['workbook.js','hash.js','workflow-schema.js','workflow-engine.js','prompt-engine.js','response-ingestion.js','project-store.js','app-core.js'];","const expected=['workbook.js','hash.js','workflow-schema.js','test-runtime.js','workflow-engine.js','prompt-engine.js','response-ingestion.js','project-store.js','app-core.js'];")
pages=pages.replace('node --check verify-test-runtime.mjs','node --check verify-test-runtime.mjs\n          node --check verify-controlling-spec.mjs',1)
pages=pages.replace('      - name: Verify generic deterministic Test IR runtime\n        run: node verify-test-runtime.mjs','      - name: Verify controlling specification invariants\n        run: node verify-controlling-spec.mjs\n      - name: Verify generic deterministic Test IR runtime\n        run: node verify-test-runtime.mjs',1)
pages=pages.replace('node build-test-project.mjs && node verify-test-runtime.mjs','node build-test-project.mjs && node verify-controlling-spec.mjs && node verify-test-runtime.mjs')
write('.github/workflows/pages.yml',pages)

